# Experimental code skeleton for ENN-based reward modeling with Double Thompson Sampling (Double TS)
# This code is a compact, implementation-oriented sketch directly tied to the described method.

# ENN ensemble: an ensemble of MLPs that each take the final LLM embedding and output a scalar reward.
class ENNEnsemble:
    def __init__(self, input_dim, hidden_dims=[128, 128], S=10, seed=None):
        self.S = S  # number of particles in the ENN
        self.models = [MLP(input_dim, hidden_dims, output_dim=1) for _ in range(S)]
        self.initial_params = [m.get_params().copy() for m in self.models]  # for regularization toward initialization
        self.rng = Random(seed)

    def predict(self, x, z):
        # x: last-layer LLM embedding; z: epistemic index in 1..S
        return self.models[z-1].forward(x).item()

    def train(self, dataset, lambda_schedule, lr_schedule, epochs):
        # dataset yields (x, y) pairs where x is embedding, y is target reward
        optimizers = [Adam(self.models[i].parameters(), lr=lr_schedule) for i in range(self.S)]
        for e in range(epochs):
            lambda_reg = lambda_schedule[e]
            for x_batch, y_batch in dataset:
                for i, m in enumerate(self.models):
                    # forward on batch
                    pred = m.forward(x_batch).squeeze()
                    # standard MSE loss
                    loss_mse = mse_loss(pred, y_batch)
                    # regularize toward initial parameters to maintain diversity
                    reg = reg_loss(m.get_params(), self.initial_params[i])
                    loss = loss_mse + lambda_reg * reg
                    optimizers[i].zero_grad()
                    loss.backward()
                    optimizers[i].step()

# Reward model wrapper (point-estimate) for comparison (optional)
class PointEstimateReward:
    def __init__(self, input_dim, hidden_dims=[128, 128]):
        self.model = MLP(input_dim, hidden_dims, output_dim=1)
    def predict(self, x):
        return self.model.forward(x).item()

# Double Thompson Sampling (Double TS) selection for a single prompt
def double_ts_select(candidates, enn_ensemble: ENNEnsemble, z1=None, z2=None, K=30):
    # candidates: list of candidate responses, each has a corresponding embedding vector
    # z1, z2: independently drawn epistemic indices in 1..S
    if z1 is None or z2 is None:
        z1 = enn_ensemble.rng.randint(1, enn_ensemble.S)
        z2 = enn_ensemble.rng.randint(1, enn_ensemble.S)

    # Compute predicted rewards under z1 for all candidates
    scores1 = [enn_ensemble.models[z1-1].forward(cand.embedding).squeeze().item() for cand in candidates]
    i1 = int(argmax(scores1))

    # Compute predicted rewards under z2 for all candidates
    scores2 = [enn_ensemble.models[z2-1].forward(cand.embedding).squeeze().item() for cand in candidates]
    # Find best candidate for z2 that is distinct from i1, with up to K attempts
    idxs2 = sorted(range(len(candidates)), key=lambda i: scores2[i], reverse=True)
    i2 = None
    for idx in idxs2:
        if idx != i1:
            i2 = idx
            break
    if i2 is None:
        # Fallback: pick the top-2 if all candidates are the same index (degenerate); else pick second-best for safety
        i2 = i1 if len(candidates) == 1 else (0 if i1 != 0 else 1)

    return candidates[i1], candidates[i2]

# Replay buffer for reward-model training
class ReplayBuffer:
    def __init__(self, capacity=3200):
        self.capacity = capacity
        self.buffer = []
    def push(self, item):
        self.buffer.append(item)
        if len(self.buffer) > self.capacity:
            self.buffer.pop(0)
    def sample(self, batch_size):
        return random.sample(self.buffer, min(batch_size, len(self.buffer)))

